{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.plus_cart_aov_upt1 AS WITH sku_mapping AS ( SELECT DISTINCT UPPER(TRIM(SKU_GROUP)) AS SKU_GROUP, LOWER(TRIM(L1_CATEGORY)) AS L1_CATEGORY FROM snitch_db.maplemonk.category_overall_data WHERE SKU_GROUP IS NOT NULL ), plus_skus AS ( SELECT DISTINCT UPPER(TRIM(SKU_GROUP)) AS SKU_GROUP FROM snitch_db.maplemonk.category_overall_data WHERE LOWER(TRIM(L1_CATEGORY)) = \'plus\' OR UPPER(TRIM(SKU_GROUP)) LIKE \'4MBG%\' OR UPPER(TRIM(SKU_GROUP)) LIKE \'4B%\' ), d2c_items AS ( SELECT CAST(f.ORDER_TIMESTAMP AS DATE) AS DATE, f.ORDER_ID, UPPER(TRIM(f.SKU_GROUP)) AS SKU_GROUP, COALESCE(f.NET_SALES, 0) AS SALES, COALESCE(f.QUANTITY, 0) AS UNITS, \'D2C\' AS CHANNEL FROM snitch_db.maplemonk.fact_items_snitch f WHERE f.ORDER_ID IS NOT NULL AND f.ORDER_TIMESTAMP IS NOT NULL ), offline_items AS ( SELECT CAST(ORDER_DATE AS DATE) AS DATE, ORDER_ID, UPPER(TRIM(SKU_GROUP)) AS SKU_GROUP, COALESCE(SELLING_PRICE, 0) AS SALES, COALESCE(SUBORDER_QUANTITY, 0) AS UNITS, \'Offline\' AS CHANNEL FROM snitch_db.maplemonk.store_fact_items_offline WHERE ORDER_ID IS NOT NULL AND ORDER_DATE IS NOT NULL AND NOT LOWER(TRIM(MARKETPLACE_MAPPED)) LIKE \'%wh%\' ), all_items AS ( SELECT DATE, ORDER_ID, SKU_GROUP, SALES, UNITS, CHANNEL FROM d2c_items UNION ALL SELECT DATE, ORDER_ID, SKU_GROUP, SALES, UNITS, CHANNEL FROM offline_items ), plus_orders AS ( SELECT DISTINCT DATE, CHANNEL, ORDER_ID FROM all_items WHERE SKU_GROUP IN ( SELECT SKU_GROUP FROM plus_skus ) ), plus_order_items AS ( SELECT a.DATE, a.CHANNEL, a.ORDER_ID, a.SKU_GROUP, a.SALES, a.UNITS, m.L1_CATEGORY FROM all_items a INNER JOIN plus_orders p ON a.DATE = p.DATE AND a.CHANNEL = p.CHANNEL AND a.ORDER_ID = p.ORDER_ID LEFT JOIN sku_mapping m ON a.SKU_GROUP = m.SKU_GROUP ), cart_level AS ( SELECT DATE, CHANNEL, ORDER_ID, SUM(SALES) AS TOTAL_SALES, SUM(UNITS) AS TOTAL_UNITS, SUM( CASE WHEN L1_CATEGORY = \'plus\' OR SKU_GROUP LIKE \'4MBG%\' OR SKU_GROUP LIKE \'4B%\' THEN SALES ELSE 0 END ) AS PLUS_SALES, SUM( CASE WHEN L1_CATEGORY = \'plus\' OR SKU_GROUP LIKE \'4MBG%\' OR SKU_GROUP LIKE \'4B%\' THEN UNITS ELSE 0 END ) AS PLUS_UNITS, MAX( CASE WHEN L1_CATEGORY IN ( \'luxe\', \'snitch\', \'ss 27\', \'ss27\' ) THEN 1 ELSE 0 END ) AS HAS_NON_PLUS, MAX( CASE WHEN L1_CATEGORY = \'long_tail\' THEN 1 ELSE 0 END ) AS HAS_NON_APPAREL FROM plus_order_items GROUP BY DATE, CHANNEL, ORDER_ID ), bucketed AS ( SELECT DATE, CHANNEL, ORDER_ID, TOTAL_SALES, TOTAL_UNITS, PLUS_SALES, PLUS_UNITS, CASE WHEN HAS_NON_PLUS = 0 AND HAS_NON_APPAREL = 0 THEN \'Plus Only\' WHEN HAS_NON_PLUS = 0 AND HAS_NON_APPAREL = 1 THEN \'Plus + Non-Apparel\' WHEN HAS_NON_PLUS = 1 AND HAS_NON_APPAREL = 0 THEN \'Plus + Non-Plus\' WHEN HAS_NON_PLUS = 1 AND HAS_NON_APPAREL = 1 THEN \'Plus + Non-Plus + Non-Apparel\' END AS BUCKET FROM cart_level ), bucket_dod AS ( SELECT DATE, CHANNEL, BUCKET, COUNT(DISTINCT ORDER_ID) AS ORDERS, SUM(PLUS_SALES) AS PLUS_SALES, SUM(TOTAL_SALES) AS TOTAL_SALES, SUM(PLUS_UNITS) AS PLUS_UNITS, SUM(TOTAL_UNITS) AS TOTAL_UNITS FROM bucketed GROUP BY DATE, CHANNEL, BUCKET ), all_plus_dod AS ( SELECT DATE, CHANNEL, \'All Plus\' AS BUCKET, COUNT(DISTINCT ORDER_ID) AS ORDERS, SUM(PLUS_SALES) AS PLUS_SALES, SUM(TOTAL_SALES) AS TOTAL_SALES, SUM(PLUS_UNITS) AS PLUS_UNITS, SUM(TOTAL_UNITS) AS TOTAL_UNITS FROM cart_level GROUP BY DATE, CHANNEL ), combined AS ( SELECT DATE, CHANNEL, BUCKET, ORDERS, PLUS_SALES, TOTAL_SALES, PLUS_UNITS, TOTAL_UNITS FROM all_plus_dod UNION ALL SELECT DATE, CHANNEL, BUCKET, ORDERS, PLUS_SALES, TOTAL_SALES, PLUS_UNITS, TOTAL_UNITS FROM bucket_dod ) SELECT DATE, CHANNEL, BUCKET, ORDERS, PLUS_SALES, TOTAL_SALES, PLUS_UNITS, TOTAL_UNITS, ROUND( TOTAL_SALES / NULLIF(ORDERS, 0), 2 ) AS AOV_TOTAL, ROUND( PLUS_SALES / NULLIF(ORDERS, 0), 2 ) AS AOV_PLUS, ROUND( TOTAL_UNITS / NULLIF(ORDERS, 0), 2 ) AS UPT FROM combined ORDER BY DATE, CASE CHANNEL WHEN \'D2C\' THEN 1 WHEN \'Offline\' THEN 2 END, CASE BUCKET WHEN \'All Plus\' THEN 1 WHEN \'Plus Only\' THEN 2 WHEN \'Plus + Non-Apparel\' THEN 3 WHEN \'Plus + Non-Plus\' THEN 4 WHEN \'Plus + Non-Plus + Non-Apparel\' THEN 5 END;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            